"""RoboPaint execution record. Only public Robot observations and actions are used."""
import sys,os,json,time,math
sys.path.insert(0,'/opt/tools')
import numpy as np
from PIL import Image
from rcb_client import Robot
OUT='/app/output'
r=Robot()
Q=[0.,1.,0.,0.]

def obs(name='current',cams=['canvas_cam','scene_cam','practice_cam'],depth=False):
    o=r.get_obs(cameras=cams,depth=depth); o.save(OUT+'/'+name)
    for cam,arr in o.last.items(): Image.fromarray(arr).save(OUT+'/'+name+'_'+cam+'.png')
    return o

def submit(a,note='',cams=[]):
    a=np.asarray(a,float)
    for k in range(0,len(a),190):
        chunk=a[k:k+190]
        before=r.status()
        with open(OUT+'/actions.jsonl','a') as f:f.write(json.dumps({'note':note,'before':before,'type':'ee_pose','dt':.05,'actions':chunk.tolist()})+'\n')
        try: res=r.submit('ee_pose',chunk,dt=.05,cameras=cams,video='none',note=note)
        except Exception:
            after=r.wait_ready()
            if after['control_steps']==before['control_steps']:res=r.submit('ee_pose',chunk,dt=.05,cameras=cams,video='none',note=note)
            else:raise
        with open(OUT+'/results.jsonl','a') as f:f.write(json.dumps(res.meta)+'\n')
        if res.stopped:raise RuntimeError('Early stop')
    return res

class Motion:
    def __init__(self):
        self.p=np.array(r.get_obs(cameras=[]).meta['proprio']['now'][7:10]);self.a=[]
    def go(self,p,speed=.08,hold=0):
        p=np.array(p,float);n=max(1,int(np.ceil(np.linalg.norm(p-self.p)/(speed*.05))))
        for t in np.linspace(0,1,n+1)[1:]:self.a.append([*(self.p*(1-t)+p*t),*Q])
        for _ in range(int(hold/.05)):self.a.append([*p,*Q])
        self.p=p
    def run(self,note=''):
        z=submit(self.a,note);self.a=[];return z

if __name__=='__main__':
    m=Motion();m.go([-.28,.18,.16],hold=.5);print(m.run('Move clear to inspect workspace').meta);obs('clear',depth=True)
PY
